\begin{proposition}
\label{proposition-sheafification-adjoint}
The canonical map $\mathcal{F} \to \mathcal{F}^\#$ has the
following universal property: For any map $\mathcal{F} \to \mathcal{G}$,
where $\mathcal{G}$ is a sheaf of sets, there is a unique map
$\mathcal{F}^\# \to \mathcal{G}$ such that $\mathcal{F} \to \mathcal{F}^\#
\to \mathcal{G}$ equals the given map.
\end{proposition}

\begin{example}
\label{example-constant-sheaf}
Let $\mathcal{C}$ be a site. Let $E$ be a set.
The {\it constant sheaf $\underline{E}$ with value $E$}
is the sheafification of the presheaf given by the constant
functor with value $E$. It is characterized by the rule
$\Mor_{\Sh(\mathcal{C})}(\underline{E}, \mathcal{F}) =
\Mor_{\textit{Sets}}(E, \Gamma(\mathcal{C}, \mathcal{F}))$
for every sheaf $\mathcal{F}$ on $\mathcal{C}$ where the
notation is from Definition \ref{definition-global-sections}.
\end{example}

\begin{lemma}
\label{lemma-colimit-sheaves}
\begin{slogan}
Colimit in category of sheaves equals sheafification of colimit in
category of presheaves.
\end{slogan}
Let $\mathcal{F} : \mathcal{I} \to \Sh(\mathcal{C})$
be a diagram. Then $\colim_\mathcal{I} \mathcal{F}$ exists
and is the sheafification of the colimit in the category of presheaves.
\end{lemma}

